class Solution {
    public String intToRoman(int num) {
        int[] values = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
        String[] symbols = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            while (num >= values[i]) {
                result.append(symbols[i]);
                num -= values[i];
            }
        }
        return result.toString();
    }
}

class Solution {
    public String intToRoman(int num) {
        int[] values = {1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1};
        String[] symbols = {"M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"};
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < values.length; i++) {
            int count = num / values[i];
            for (int j = 0; j < count; j++) {
                result.append(symbols[i]);
            }
            num %= values[i];
        }
        return result.toString();
    }
}

class Solution {
    public String intToRoman(int num) {
        String[] thousands = {"", "M", "MM", "MMM"};
        String[] hundreds = {"", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"};
        String[] tens = {"", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"};
        String[] ones = {"", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"};
        return thousands[num / 1000]
                + hundreds[(num % 1000) / 100]
                + tens[(num % 100) / 10]
                + ones[num % 10];
    }
}

class Solution {
    public String intToRoman(int num) {
        StringBuilder result = new StringBuilder();
        appendRepeat(result, 'M', num / 1000);
        appendDigit(result, (num / 100) % 10, 'C', 'D', 'M');
        appendDigit(result, (num / 10) % 10, 'X', 'L', 'C');
        appendDigit(result, num % 10, 'I', 'V', 'X');
        return result.toString();
    }

    private void appendDigit(StringBuilder result, int digit, char one, char five, char ten) {
        if (digit == 9) {
            result.append(one).append(ten);
        } else if (digit >= 5) {
            result.append(five);
            appendRepeat(result, one, digit - 5);
        } else if (digit == 4) {
            result.append(one).append(five);
        } else {
            appendRepeat(result, one, digit);
        }
    }

    private void appendRepeat(StringBuilder result, char symbol, int count) {
        for (int i = 0; i < count; i++) {
            result.append(symbol);
        }
    }
}

class Solution {
    public String intToRoman(int num) {
        StringBuilder additive = new StringBuilder();
        num = appendChunk(additive, num, 1000, "M");
        num = appendChunk(additive, num, 500, "D");
        num = appendChunk(additive, num, 100, "C");
        num = appendChunk(additive, num, 50, "L");
        num = appendChunk(additive, num, 10, "X");
        num = appendChunk(additive, num, 5, "V");
        appendChunk(additive, num, 1, "I");

        return additive.toString()
                .replace("DCCCC", "CM")
                .replace("CCCC", "CD")
                .replace("LXXXX", "XC")
                .replace("XXXX", "XL")
                .replace("VIIII", "IX")
                .replace("IIII", "IV");
    }

    private int appendChunk(StringBuilder builder, int num, int value, String symbol) {
        int count = num / value;
        for (int i = 0; i < count; i++) {
            builder.append(symbol);
        }
        return num % value;
    }
}
